import{c as r,Q as a,j as d,m as o}from"./chunks/framework.BPKcPtvA.js";const e="/screenshots/wishlist.png",l="/screenshots/wishlist-card.png",u=JSON.parse('{"title":"スキリスト画面","description":"","frontmatter":{},"headers":[],"relativePath":"guide/wishlist.md","filePath":"guide/wishlist.md","lastUpdated":1786391114000}'),i={name:"guide/wishlist.md"};function n(h,t,s,c,g,b){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="スキリスト画面" tabindex="-1">スキリスト画面 <a class="header-anchor" href="#スキリスト画面" aria-label="Permalink to &quot;スキリスト画面&quot;">​</a></h1><p>BOOTH の <strong>スキリスト</strong> をアプリ側にも同期して、気になるアイテムを一覧する画面です。 購入済みかどうかもバッジで確認できます。</p><h2 id="ライブラリ画面との違い" tabindex="-1">ライブラリ画面との違い <a class="header-anchor" href="#ライブラリ画面との違い" aria-label="Permalink to &quot;ライブラリ画面との違い&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>ライブラリ</th><th>スキリスト</th></tr></thead><tbody><tr><td>表示対象</td><td>購入済みアイテム</td><td>BOOTH のスキリストに入れたもの</td></tr><tr><td>主な操作</td><td>ダウンロード / 詳細 / カテゴリ付け</td><td>一覧 / 削除 / リスト分け / ライブラリへ追加</td></tr><tr><td>追加経路</td><td>BOOTH ライブラリ取り込み / URL 受信</td><td>BOOTH スキリスト同期 + 手動 URL 追加</td></tr><tr><td>購入後の扱い</td><td>そのまま表示</td><td>所持バッジを付けて、そのまま表示</td></tr></tbody></table><h2 id="主な構成" tabindex="-1">主な構成 <a class="header-anchor" href="#主な構成" aria-label="Permalink to &quot;主な構成&quot;">​</a></h2><p><img src="'+e+'" alt="スキリスト画面 — 名前付きリストのタブとカード一覧"></p><p>上から <strong>ツールバー</strong> / <strong>リストタブ</strong> (BOOTH の名前付きリストごと) / <strong>カード一覧</strong> (ライブラリと同じ形)、右下に <strong>追加ボタン</strong>。値下がりしたアイテムには <code>↓N%</code> タグが付きます。</p><p><img src="'+l+'" alt="スキリストのカード — カテゴリ / R-18 / 価格 のタグ"></p><blockquote><p>画面内の商品名・ショップ名はデモ用の架空データです。</p></blockquote><h2 id="ツールバー" tabindex="-1">ツールバー <a class="header-anchor" href="#ツールバー" aria-label="Permalink to &quot;ツールバー&quot;">​</a></h2><p>ライブラリ画面と並び順・挙動が揃っています (検索履歴や保存した条件は独立)。</p><table tabindex="0"><thead><tr><th>ボタン</th><th>動作</th></tr></thead><tbody><tr><td>🔍 検索</td><td>商品名 / ショップ名 / カテゴリ / リスト名を部分一致で検索。ライブラリと同じ <code>shop:</code> / <code>tag:</code> / <code>memo:</code> / <code>-</code> 除外に対応</td></tr><tr><td>↕ 並び</td><td>追加日 (新しい / 古い) / 名前 / 価格 (高い / 安い) / ショップ名 で並び替え</td></tr><tr><td>▦ グループ表示</td><td>選んだ軸で見出し付きのセクションに分けて表示 (後述)</td></tr><tr><td>▽ 絞り込み</td><td>カテゴリ / ショップ / 状態 / リスト / VRChat / R-18 を複数選択 (パネル上部の検索欄で候補を絞り込み)</td></tr><tr><td>⋯ 表示オプション</td><td>R-18 / 「✓ 購入済」表示 / 最近削除を表示 など</td></tr><tr><td>↺ BOOTH と同期</td><td>BOOTH スキリストを全ページ取得 → 手元のスキリストと統合 (既存を消さず追加分だけ)</td></tr></tbody></table><p>同期中の手順と進み具合は <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> で確認でき、そこから中止もできます。</p><h3 id="複合検索" tabindex="-1">複合検索 <a class="header-anchor" href="#複合検索" aria-label="Permalink to &quot;複合検索&quot;">​</a></h3><p><a href="/guide/library#複合検索">ライブラリの複合検索</a>と同じ構文を使えます。通常の 検索語は商品名 / ショップ名 / カテゴリ / リスト名を対象にし、空白区切りで AND、<code>&quot;...&quot;</code> で連続した語句を検索します。</p><table tabindex="0"><thead><tr><th>入力</th><th>スキリストでの検索対象</th></tr></thead><tbody><tr><td><code>shop:alice</code></td><td>ショップ名または BOOTH subdomain</td></tr><tr><td><code>tag:VRChat</code></td><td>BOOTH の商品タグ。旧データは次回以降の起動・同期で順次補完</td></tr><tr><td><code>memo:候補</code></td><td>ライブラリと共通のアイテムメモ全文</td></tr><tr><td><code>-tag:Quest</code></td><td>該当タグを持つ商品を除外</td></tr></tbody></table><p>カードのサイズは、リストタブ行の右端 <strong>⊞ (サイズ)</strong> ボタンから ライブラリと同じ画面 (小 / 中 / 大 + カスタムの横・縦スライダー) で調整します。</p><h3 id="グループ表示" tabindex="-1">グループ表示 <a class="header-anchor" href="#グループ表示" aria-label="Permalink to &quot;グループ表示&quot;">​</a></h3><p>▦ ボタンで、一覧を選んだ軸ごとの見出し付きセクションに分けて表示できます。 軸は <strong>リスト / BOOTH カテゴリ / ショップ / 追加時期 / 価格帯</strong> から選べます。 「グループ化なし」で通常の一覧に戻ります。</p><ul><li><strong>見出しをクリックで開閉</strong> できます (件数付き)。開閉の状態は軸ごとに記憶します。</li><li><strong>BOOTH カテゴリ</strong>は親カテゴリの中に子カテゴリの見出しが入る 2 段構成です。</li><li><strong>リスト</strong>の軸では、複数のリストに入れている商品はその各セクションに繰り返し 表示され、どちらのカードで選んでも同じ 1 商品として扱われます。名前付きリストに 入れていない商品は「未分類」にまとまります。セクションになるのは <strong>いま見えて いるリストだけ</strong> です — リストごとのタブを開いているときはそのリスト、絞り込みで リストを選んでいるときは選んだリストのみで、複数所属の商品があっても表示外の リストのセクションは出ません。</li><li><strong>追加時期</strong>は 1週間以内 / 1か月以内 / 1年以内 / それ以前、<strong>価格帯</strong> は 無料 / ¥1,000 以下 / ¥3,000 以下 / ¥10,000 以下 / ¥10,000 超 に分かれます。 この 2 つは件数の多い順ではなく、新しい順・安い順に並びます。価格をまだ取得 できていない商品は「価格不明」にまとまります (「無料」には入りません)。</li><li>絞り込み・検索・並び順はグループ表示中もそのまま効きます (セクション内で並びます)。</li><li>表示中のリストタブの中身がセクションに分かれます。</li></ul><h3 id="r-18-表示はライブラリと連動" tabindex="-1">R-18 表示はライブラリと連動 <a class="header-anchor" href="#r-18-表示はライブラリと連動" aria-label="Permalink to &quot;R-18 表示はライブラリと連動&quot;">​</a></h3><p>既定では、<strong>⋯ 表示オプション → R-18 商品を表示</strong> の切替がライブラリ画面と連動します。 スキリスト側で切り替えるとライブラリ側も同じ状態になり、その逆も同じです。 設定で連動を解除すると、スキリストだけ独立して切り替えられます。</p><h2 id="リストタブ-booth-のリスト分け" tabindex="-1">リストタブ (BOOTH のリスト分け) <a class="header-anchor" href="#リストタブ-booth-のリスト分け" aria-label="Permalink to &quot;リストタブ (BOOTH のリスト分け)&quot;">​</a></h2><p>BOOTH のスキリストは「名前付きリスト」に分けられます。 そのリスト構造をそのまま反映してタブとして並びます。</p><ul><li><strong>すべて</strong> タブ (左端、デフォルトで選択中) は全項目を重複なくまとめて表示</li><li><strong>「未分類」</strong> タブ は BOOTH の「リスト名のない」スキリスト</li><li>それ以外は BOOTH 側のユーザ作成リスト名そのまま</li><li>1 つの項目が複数リストに属している場合、<strong>それぞれのタブに重複して表示</strong> (BOOTH と同じ)</li><li>タブが横に溢れたときは <strong>＜ / ＞</strong> ボタンで横スクロール</li></ul><h3 id="タブ右クリック" tabindex="-1">タブ右クリック <a class="header-anchor" href="#タブ右クリック" aria-label="Permalink to &quot;タブ右クリック&quot;">​</a></h3><p>タブを右クリックすると <strong>そのタブ内の全アイテムへの一括操作</strong> メニューが出ます。 選択モードに入らなくても 1 クリックで「このリスト全部を…」できる便利機能です。</p><h2 id="カード操作" tabindex="-1">カード操作 <a class="header-anchor" href="#カード操作" aria-label="Permalink to &quot;カード操作&quot;">​</a></h2><p>ライブラリのカードとほぼ同じ + 以下の違い:</p><table tabindex="0"><thead><tr><th>キー操作</th><th>動作</th></tr></thead><tbody><tr><td>左クリック</td><td>BOOTH 商品ページを外部ブラウザで開く (ライブラリと違って詳細画面は無い)</td></tr><tr><td>× (右上)</td><td>スキリストから削除 (BOOTH 側も同時に削除 → 削除履歴として残る)</td></tr><tr><td>Ctrl + 左クリック</td><td>一括選択モード</td></tr><tr><td>← ↑ → ↓ / Home / End</td><td>カードを移動 (キーボード)</td></tr><tr><td>Enter</td><td>商品ページを開く (選択モード中は選択の切替)</td></tr><tr><td>Delete</td><td>スキリストから削除</td></tr><tr><td>右クリック</td><td>商品ページを開く / 📈 価格の推移 / 🏪 ショップを開く / ライブラリに追加 / リスト変更 / カテゴリ編集 / メモ編集 / 削除</td></tr></tbody></table><h3 id="一括削除の確認ダイアログ" tabindex="-1">一括削除の確認ダイアログ <a class="header-anchor" href="#一括削除の確認ダイアログ" aria-label="Permalink to &quot;一括削除の確認ダイアログ&quot;">​</a></h3><p>一括選択モードから「BOOTH からも削除」を選ぶと、件数 / 対象アイテム名 (5 件以下は全件、それ以上は先頭 2 件 + 残数) / 「元に戻すには BOOTH で再度ハートする必要があります」という警告が出る確認ダイアログを通します。 BOOTH 側の削除は取り消せないので、誤操作の防止を確認ダイアログで担保します。</p><h3 id="所持バッジ-✓-購入済-所有済-追加済" tabindex="-1">所持バッジ (✓ 購入済 / 所有済 / 追加済) <a class="header-anchor" href="#所持バッジ-✓-購入済-所有済-追加済" aria-label="Permalink to &quot;所持バッジ (✓ 購入済 / 所有済 / 追加済)&quot;">​</a></h3><p>スキリストのアイテムが手元のライブラリにもある場合、どう手に入れたかに応じて カードにバッジが付き、薄く表示になります:</p><table tabindex="0"><thead><tr><th>バッジ</th><th>付く条件</th></tr></thead><tbody><tr><td><code>✓ 購入済</code></td><td>BOOTH で <strong>購入</strong> した商品</td></tr><tr><td><code>✓ 所有済</code></td><td><strong>ギフト</strong> で受け取った商品</td></tr><tr><td><code>✓ 追加済</code></td><td>無料ダウンロード / URL 手動追加 など、上記以外でライブラリにある商品</td></tr></tbody></table><p>絞り込みの「状態」でも、未所持 / 購入済 / 所有済 / 追加済 を個別に選べます。</p><p>設定の「✓ 購入済を表示」を OFF にすると、これらのバッジ付きアイテムを一覧から 隠せます。項目自体は削除されず、表示を ON に戻せば再び表示されます。</p><h3 id="値下がりタグ-↓n" tabindex="-1">値下がりタグ (↓N%) <a class="header-anchor" href="#値下がりタグ-↓n" aria-label="Permalink to &quot;値下がりタグ (↓N%)&quot;">​</a></h3><p>セール中のアイテムには <code>↓ N%</code> タグが付きます。</p><ul><li><code>N%</code> は、そのアイテムで <strong>一番値引き率が大きいバリエーション</strong> の割引率</li><li>タグにマウスを乗せると、値下がりした全バリエーションを <strong>¥元値 → ¥現在価格 (X% off)</strong> の一覧で確認できます</li><li>セールが終わると、タグは自動的に消えます</li></ul><h3 id="価格の推移" tabindex="-1">価格の推移 <a class="header-anchor" href="#価格の推移" aria-label="Permalink to &quot;価格の推移&quot;">​</a></h3><p>カードを右クリック →「📈 価格の推移」で、その商品の値段が今までどう動いたかを グラフで見られます。</p><ul><li>値段は途中で少しずつ変わるものではないので、<strong>階段状</strong>のグラフです</li><li>グラフにマウスを乗せると、<strong>その時の値段と「いつからいつまでその値段だったか」</strong> が出ます。← → キーでも同じように、値段が変わった時点を順にたどれます</li><li>今売られているバリエーションだけを表示します (販売終了したバリエーションの 記録は残っていますが、グラフには出しません)</li><li>グラフの下に、<strong>いつからの記録か (何日分か)</strong> と <strong>どこのデータか</strong> が出ます</li></ul><h4 id="記録はいつ増えるか" tabindex="-1">記録はいつ増えるか <a class="header-anchor" href="#記録はいつ増えるか" aria-label="Permalink to &quot;記録はいつ増えるか&quot;">​</a></h4><p>値段のチェックは <strong>アプリを起動したとき</strong> と <strong>手動で同期したとき</strong> に行います (間隔は設定の「スキリスト値下げチェック間隔」で決まります)。 そのため、<strong>アプリを起動していない間の値動きは記録されません</strong> — 数時間で終わるセールなどは、丸ごと抜けることがあります。</p><h4 id="グラフに出るデータの出どころ" tabindex="-1">グラフに出るデータの出どころ <a class="header-anchor" href="#グラフに出るデータの出どころ" aria-label="Permalink to &quot;グラフに出るデータの出どころ&quot;">​</a></h4><p>グラフの下に <code>Source:</code> として表示されます。</p><table tabindex="0"><thead><tr><th>表示</th><th>意味</th></tr></thead><tbody><tr><td><code>ローカル観測</code></td><td>この PC が実際にチェックして記録した値段</td></tr><tr><td><code>Boopa</code></td><td><a href="https://mametarogg.github.io/" target="_blank" rel="noreferrer">Boopa</a> が公開している価格データ (VRChat 関連商品が中心)</td></tr></tbody></table><p>Boopa のデータは、この PC で記録を取り始める前の期間も埋めてくれます。 対象外の商品では表示されず、<code>Source: ローカル観測</code> だけになります。</p><p>Boopa のデータを取りに行くとき、<strong>表示している商品の ID だけ</strong>が当アプリの サーバーを経由します (詳しくは<a href="/guide/settings#外部との通信">設定の「外部との通信」</a>)。</p><h2 id="一括操作-選択モード" tabindex="-1">一括操作 (選択モード) <a class="header-anchor" href="#一括操作-選択モード" aria-label="Permalink to &quot;一括操作 (選択モード)&quot;">​</a></h2><p>カードを <strong>Ctrl + 左クリック</strong> するか、ツールバーの一括選択ボタンで選択モードに入ります。 選択中は画面に <strong>「N 件選択」バー</strong> が表示されます。</p><p>選択中は次のキーが使えます (既定):</p><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td>Ctrl + A</td><td>表示中のカードをすべて選択</td></tr><tr><td>Ctrl + I</td><td>選択を反転</td></tr><tr><td>Ctrl + D</td><td>選択を解除</td></tr><tr><td>Esc</td><td>選択モードを抜ける</td></tr></tbody></table><p>選択したカードを右クリックすると一括操作メニューが出ます:</p><table tabindex="0"><thead><tr><th>メニュー</th><th>動作</th></tr></thead><tbody><tr><td>📥 ライブラリに追加</td><td>選択したアイテムをまとめてライブラリに取り込み</td></tr><tr><td>🔖 リストを変更</td><td>選択したアイテムの名前付きリスト所属をまとめて変更 (下記)</td></tr><tr><td>📋 おすすめリストとしてエクスポート</td><td>後述の「エクスポート」参照</td></tr><tr><td>🗑️ BOOTH からも削除</td><td>上記「一括削除の確認ダイアログ」参照</td></tr></tbody></table><p><strong>タブを右クリック</strong> すると、選択モードに入らなくても同じメニューを <strong>そのタブ内の全アイテム</strong> に対して実行できます。</p><h3 id="リスト変更の-3-状態チェック" tabindex="-1">リスト変更の 3 状態チェック <a class="header-anchor" href="#リスト変更の-3-状態チェック" aria-label="Permalink to &quot;リスト変更の 3 状態チェック&quot;">​</a></h3><p>複数のアイテムを選んで「リストを変更」すると、各リストのチェックが 3 状態になります:</p><ul><li><strong>チェックあり</strong> — 選択した全アイテムをそのリストに入れる</li><li><strong>チェックなし</strong> — 選択した全アイテムをそのリストから外す</li><li><strong>− (混在)</strong> — アイテムによって所属がバラバラの状態。<strong>そのままにすると各アイテムの 現状を保持</strong> します (混在しているリストを誤ってまとめて変更しない安全策)</li></ul><h2 id="手動追加-右下の-ボタン" tabindex="-1">手動追加 (右下の ＋ ボタン) <a class="header-anchor" href="#手動追加-右下の-ボタン" aria-label="Permalink to &quot;手動追加 (右下の ＋ ボタン)&quot;">​</a></h2><p>右下の ＋ ボタンで BOOTH 商品 URL を貼り付けて追加できます。</p><ul><li><code>https://booth.pm/ja/items/12345</code> 形式の URL を貼って Enter</li><li>クリップボードに BOOTH 商品 URL が入っていれば、開いた時点で入力欄に自動で入ります</li><li>商品情報 (名前 / 価格 / カテゴリ / ショップ / R-18 など) を自動取得</li><li><strong>振り分け先リスト (複数選択可)</strong> — 名前付きリストにチェックを入れると、 追加と同時にそのリストへ振り分けます (未選択なら未分類)</li><li>まだ BOOTH スキリストに入っていない場合は <strong>BOOTH 側にも追加</strong> されます</li><li>商品追加後にリスト振り分けだけ失敗した場合は、確認できていない所属をローカルへ 推測反映せず、未分類として追加して「一部未反映」を表示します</li></ul><h2 id="自動同期と購入連動" tabindex="-1">自動同期と購入連動 <a class="header-anchor" href="#自動同期と購入連動" aria-label="Permalink to &quot;自動同期と購入連動&quot;">​</a></h2><h3 id="起動時-手動同期" tabindex="-1">起動時 + 手動同期 <a class="header-anchor" href="#起動時-手動同期" aria-label="Permalink to &quot;起動時 + 手動同期&quot;">​</a></h3><ul><li>起動直後は手元のスキリストの内容をすぐ表示</li><li>「🔄 BOOTH と同期」で BOOTH スキリストを全ページ取得して統合 (= 既存の項目を消さず、追加だけ)</li><li>実行中のメッセージに「数百件あると 10 秒以上かかります」が出る</li><li>リスト構造の自動取得は最大 24 時間に 1 回。価格・タグの取得に失敗した商品は、 リスト全体を再取得せず、その商品だけを 1 時間以上空けて再試行</li><li>一部商品の価格・タグを取得できなかった場合も、取得できたリスト構造は保存され、 手動同期の完了通知には「一部未完了」と表示</li><li>ページ取得やページネーションが不完全なリストは、保存済みの所属・名称を消さず、 24 時間の完了時計も進めないため、次回起動で構造取得を再試行</li></ul><h3 id="購入検知" tabindex="-1">購入検知 <a class="header-anchor" href="#購入検知" aria-label="Permalink to &quot;購入検知&quot;">​</a></h3><p>ライブラリの取得時に、スキリストに入れていたアイテムを購入済みと検出すると、 スキリストには残したまま、入手方法に応じて <code>✓ 購入済</code> / <code>✓ 所有済</code> / <code>✓ 追加済</code> のバッジを付けます。</p><p>不要になった項目は、カード右上の ×、Delete キー、または右クリックメニューから 手動で削除してください。BOOTH 側のスキリストからも削除され、「最近削除」履歴に残ります。</p><h3 id="「最近削除」履歴" tabindex="-1">「最近削除」履歴 <a class="header-anchor" href="#「最近削除」履歴" aria-label="Permalink to &quot;「最近削除」履歴&quot;">​</a></h3><p>削除した項目を後から確認 / 戻せるように、削除履歴として残します。 履歴は、再追加するか「履歴から完全削除」を実行するまで残ります。</p><ul><li>表示オプション 🗑️ 「最近削除を表示」を ON にすると赤帯のカードとして表示</li><li>右クリックメニューから <strong>「🔖 BOOTH に再追加」</strong> で復元可能</li><li>商品の再追加には成功して所属リストの復元だけに失敗した場合、商品は通常表示へ戻し、 「一部未反映」の警告で BOOTH 側のリスト確認を案内</li><li><strong>「⚠️ 履歴から完全削除」</strong> で削除履歴からも消す</li></ul><h2 id="保存した絞り込み条件" tabindex="-1">保存した絞り込み条件 <a class="header-anchor" href="#保存した絞り込み条件" aria-label="Permalink to &quot;保存した絞り込み条件&quot;">​</a></h2><p>絞り込み + 並び順をまとめて名前付きで保存できます (絞り込みパネル上部から)。 ライブラリ画面の保存条件と同じ操作感で使えます。ライブラリとは別のデータとして 保存するので、互いに影響しません。</p><h2 id="エクスポート-おすすめリスト" tabindex="-1">エクスポート (おすすめリスト) <a class="header-anchor" href="#エクスポート-おすすめリスト" aria-label="Permalink to &quot;エクスポート (おすすめリスト)&quot;">​</a></h2><p>一括選択モード → 右クリック「📋 N 件をおすすめリストとしてエクスポート」で Markdown / JSON のどちらかにエクスポートします (保存先を選ぶダイアログが開く)。</p><ul><li>Markdown: カスタムカテゴリ別のグループ + メモを引用で</li><li>JSON: 保存や他ツールでの処理に向く構造化形式</li></ul>',77)])])}const O=r(i,[["render",n]]);export{u as __pageData,O as default};
